const item = $input.first().json;
const body = item.body || item;

// Sanitiser l'email : supprimer les caracteres de controle et injections
let email = (body.email || '').split(/[\r\n]/)[0].trim().toLowerCase();

// Valider le format email basique
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email)) {
  throw new Error('Email invalide : ' + email);
}

const domaine = email.split('@')[1] || '';

const domainesGeneriques = [
  'gmail.com', 'outlook.com', 'outlook.fr', 'yahoo.fr', 'yahoo.com',
  'hotmail.com', 'hotmail.fr', 'live.fr', 'live.com',
  'orange.fr', 'free.fr', 'sfr.fr', 'wanadoo.fr', 'laposte.net',
  'icloud.com', 'protonmail.com', 'pm.me'
];

const domaineEntreprise = domainesGeneriques.includes(domaine) ? null : domaine;

// GARDE-FOU anti-hallucination : verifier qu'un vrai site accessible existe
// avant tout enrichissement. Un domaine d'email (ex: durand-conseil.fr) n'implique pas
// un site web exploitable ; sans site verifie, on n'enrichit pas.
let siteActif = false;
let siteUrlVerifiee = null;
if (domaineEntreprise) {
  for (const u of ['https://' + domaineEntreprise, 'http://' + domaineEntreprise]) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: u,
        timeout: 6000,
        followRedirect: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
      });
      const code = resp.statusCode || 0;
      const len = (typeof resp.body === 'string') ? resp.body.length : 0;
      if (code >= 200 && code < 400 && len > 500) {
        siteActif = true;
        siteUrlVerifiee = u;
        break;
      }
    } catch (e) {
      // domaine injoignable sur cette URL, on tente la suivante
    }
  }
}

const scoreGlobal = parseFloat(body.score_global) || 0;
let niveauGlobal = 'Debutant';
if (scoreGlobal >= 3.4) niveauGlobal = 'Integre';
else if (scoreGlobal >= 2.6) niveauGlobal = 'Structure';
else if (scoreGlobal >= 1.8) niveauGlobal = 'Explorateur';

// Sanitiser aussi prenom/nom/entreprise
const sanitize = (s) => (s || '').replace(/[\r\n]/g, '').trim();

return [{
  json: {
    email: email,
    prenom: sanitize(body.prenom),
    nom: sanitize(body.nom),
    entreprise: sanitize(body.entreprise),
    taille_equipe: sanitize(body.taille_equipe) || null,
    domaine: domaineEntreprise,
    siteActif: siteActif,
    siteUrlVerifiee: siteUrlVerifiee,
    niveauGlobal: niveauGlobal,
    score_usages: parseFloat(body.score_usages) || 0,
    score_donnees: parseFloat(body.score_donnees) || 0,
    score_competences: parseFloat(body.score_competences) || 0,
    score_processus: parseFloat(body.score_processus) || 0,
    score_gouvernance: parseFloat(body.score_gouvernance) || 0,
    score_global: scoreGlobal
  }
}];

const prospect = $('Extraire domaine email').first().json;

// Parser la reponse Perplexity
let parsed = null;
let citations = [];
try {
  const perplexity = $('Rechercher entreprise Perplexity').first().json;
  citations = perplexity.citations || [];
  let content = (perplexity.choices && perplexity.choices[0] && perplexity.choices[0].message && perplexity.choices[0].message.content) || '';
  content = content.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    let p = JSON.parse(content);
    if (Array.isArray(p)) p = p[0];
    parsed = p;
  } catch (e) {
    parsed = null;
  }
} catch (e) {
  parsed = null;
}

// GARDE-FOU anti-hallucination : le contexte entreprise n'est utilise QUE si
// (1) un vrai site accessible a ete verifie (siteActif) ET
// (2) Perplexity confirme avoir trouve l'entreprise (found !== false).
const found = !!(parsed && parsed.found !== false);
const contexteVerifie = prospect.siteActif === true && found === true && !!parsed;

let contexteEntreprise = null;
let contexteTexte = '';
if (contexteVerifie) {
  contexteEntreprise = parsed;
  const c = parsed;
  const ok = (v) => v && v !== 'Non disponible' && String(v).trim() !== '';
  const parts = [];
  if (ok(c.secteur)) parts.push('Secteur : ' + c.secteur);
  if (ok(c.description)) parts.push('Activite : ' + c.description);
  if (ok(c.taille_estimee)) parts.push('Taille : ' + c.taille_estimee);
  if (ok(c.services_produits)) parts.push('Services/Produits : ' + c.services_produits);
  if (ok(c.clients_cibles)) parts.push('Clients cibles : ' + c.clients_cibles);
  if (ok(c.presence_digitale)) parts.push('Presence digitale : ' + c.presence_digitale);
  if (ok(c.enjeux_sectoriels)) parts.push('Enjeux sectoriels : ' + c.enjeux_sectoriels);
  contexteTexte = parts.join('\n');
  if (citations.length > 0) {
    contexteTexte += '\n\nSources : ' + citations.slice(0, 5).join(', ');
  }
}

const contexteDisponible = contexteTexte.trim() !== '';

return [{
  json: {
    ...prospect,
    contexteEntreprise: contexteEntreprise,
    contexteTexte: contexteDisponible ? contexteTexte : 'Aucune information entreprise verifiee disponible. Ne fais aucune supposition sur cette entreprise, fonde-toi uniquement sur les scores et les reponses au questionnaire.',
    contexteDisponible: contexteDisponible,
    citations: contexteDisponible ? citations : []
  }
}];

const prospect = $('Preparer prompt Gemini').first().json;

// Parser reponse Gemini #1 (analyse dimensions)
const gemini1Raw = $('Analyser dimensions').first().json;
let analyse1 = {};
try {
  const text1 = gemini1Raw.candidates[0].content.parts[0].text;
  analyse1 = typeof text1 === 'string' ? JSON.parse(text1) : text1;
  if (Array.isArray(analyse1)) analyse1 = analyse1[0];
} catch(e) {
  throw new Error('Erreur parsing Gemini #1 : ' + e.message);
}

// Parser reponse Gemini #2 (plan action)
const gemini2Raw = $('Generer plan action').first().json;
let analyse2 = {};
try {
  const text2 = gemini2Raw.candidates[0].content.parts[0].text;
  analyse2 = typeof text2 === 'string' ? JSON.parse(text2) : text2;
  if (Array.isArray(analyse2)) analyse2 = analyse2[0];
} catch(e) {
  throw new Error('Erreur parsing Gemini #2 : ' + e.message);
}

// Generer magic token (64 chars hex) sans module crypto
const hexChars = '0123456789abcdef';
let magicToken = '';
for (let i = 0; i < 64; i++) {
  magicToken += hexChars.charAt(Math.floor(Math.random() * 16));
}

// Expiration : now + 30 jours
const tokenExpiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

// URL complete du rapport
const rapportUrl = 'https://example.com/diagnostic/rapport/?token=' + magicToken;

// Calculer dimension forte et faible
const dimensions = [
  { nom: 'Usages IA actuels', score: prospect.score_usages },
  { nom: 'Donnees marketing', score: prospect.score_donnees },
  { nom: 'Competences et culture', score: prospect.score_competences },
  { nom: 'Processus et workflows', score: prospect.score_processus },
  { nom: 'Gouvernance et vision', score: prospect.score_gouvernance }
];
const sorted = [...dimensions].sort((a, b) => b.score - a.score);
const dimensionForte = sorted[0].nom + ' (' + sorted[0].score + ')';
const dimensionFaible = sorted[sorted.length - 1].nom + ' (' + sorted[sorted.length - 1].score + ')';

// Contexte entreprise depuis Perplexity
const contexteEntreprise = prospect.contexteEntreprise || null;

// Assembler le JSON final pour Supabase
const rapport = {
  email: prospect.email,
  magic_token: magicToken,
  token_expires_at: tokenExpiresAt,
  prenom: prospect.prenom,
  nom: prospect.nom,
  entreprise: prospect.entreprise,
  taille_equipe: prospect.taille_equipe || null,
  date_diagnostic: new Date().toISOString(),
  score_usages: prospect.score_usages,
  score_donnees: prospect.score_donnees,
  score_competences: prospect.score_competences,
  score_processus: prospect.score_processus,
  score_gouvernance: prospect.score_gouvernance,
  score_global: prospect.score_global,
  contexte_entreprise: contexteEntreprise,
  analyse: {
    intro_personnalisee: analyse1.intro_personnalisee || '',
    synthese_globale: analyse1.synthese_globale || '',
    dimensions: analyse1.dimensions || [],
    actions: analyse2.actions || []
  }
};

// Donnees supplementaires pour Brevo
const brevoExtra = {
  niveauMaturite: prospect.niveauGlobal,
  dimensionForte: dimensionForte,
  dimensionFaible: dimensionFaible,
  rapportSynthese: (analyse1.synthese_globale || '').substring(0, 500),
  rapportUrl: rapportUrl
};

return [{ json: { ...rapport, brevoExtra } }];
